return O._levelMod[yi]or nil
end
O._levelMod[yi]=false
local zi=H.Levels[yi]
local Ai=type(zi)==ioc[1408]and H.Waves[zi.waves or yi]
local Bi=type(Ai)==ioc[1408]and Ai.initial_unit_configs
if type(Bi)~=ioc[1408]then
return nil
