local Ci,Di,Ei={},{},0
for Fi,Gi in pairs(Bi)do
local Hi=type(Gi)==ioc[1408]and type(Gi.override_stats)==ioc[1408]and(Gi.override_stats[1]or Gi.override_stats[ioc[1545]])or nil
if type(Hi)==ioc[1408]then
local Ii=tonumber(Hi.health)or 20
Ei=Ei+Ii
table.insert(Ci,{hp=Ii,st=Hi})
for Ji in pairs(Hi)do
local Ki=tostring(Ji):match(ioc[1546])or tostring(Ji):match(ioc[1547])
if Ki then
Di[Ki]=true
end
end
end
end
if not next(Di)or Ei<=0 then
return nil
end
local Li={weak={},strong={},res={}}
for Mi in pairs(Di)do
local Ni=0
for Oi,Pi in ipairs(Ci)do
local Qi=(1+(tonumber(Pi.st[ioc[1548]..Mi])or 0))*100/(100+math.max(0,tonumber(Pi.st[ioc[1549]..Mi])or 0))
Ni=Ni+Pi.hp/math.max(0.05,Qi)
