function eb.board()
local ll=H.core(ioc[1589])
local ml=H.prof()
if not(ll and ml)then
return nil
end
local nl=ll.get_board(G.UserId)
if not nl then
return nil
end
local ol=type(ml._summer2_hunt_wins)==ioc[1408]and ml._summer2_hunt_wins or{}
local pl,ql,rl=ol.maps or{},ol.weathers or{},ml._summer2_map_board_claimed_lines or{}
local sl,tl,ul=0,0,0
for vl,wl in ipairs(nl)do
if pl[wl]then
sl=sl+1
end
end
for xl in pairs(ll.get_completed_lines(nl,pl))do
tl=tl+1
end
for yl in pairs(ql)do
ul=ul+1
end
return{core=ll,board=nl,maps=pl,weathers=ql,claimed=rl,squares=sl,lines=tl,weathersWon=ul,total= #ll.LINES,claimable=ll.get_claimable_lines(nl,pl,rl)}
end
function eb.lineGems()
return 2000*I.pearlValue+10*(H.ITEM_VALUE.star_remnant_limited or 25)
