function eb.firstValue(zl,Al)
local Bl=eb.board()
if not Bl then
return 0,{}
end
local Cl,Dl=0,{}
local El=zl and table.find(Bl.board,zl)
if El and not Bl.maps[zl]then
local Fl=0
for Gl,Hl in ipairs(Bl.core.LINES)do
if table.find(Hl.cells,El)then
Fl=Fl+1
end
end
Cl=Cl+Fl*eb.lineGems()/Bl.core.SIZE
table.insert(Dl,ioc[1590])
end
if Al and Al~=ioc[1591]and not Bl.weathers[Al]then
Cl=Cl+(1000+5000*I.pearlValue+50*(H.ITEM_VALUE.star_remnant_limited or 25))/eb.WEATHERS
table.insert(Dl,ioc[1592])
end
if not next(Bl.maps)then
Cl=Cl+500+4500*I.pearlValue+200
table.insert(Dl,ioc[1593])
end
return Cl,Dl
end
