return{key=ioc[1594]..tostring(Jl.level),kind=ioc[1425],level=Jl.level,diff=ioc[1596],value=Ml*I.pearlValue+Nl,coins=Ml,p0=0.5,label=ioc[1597],why=string.format(ioc[1598],math.floor(Ml),Jl.weather and Pl[Jl.weather]and(ioc[1599]..Pl[Jl.weather].name)or ioc[337],#Ol>0 and(ioc[1600]..table.concat(Ol,ioc[1503]))or ioc[337])}
