function eb.weatherStrength(om)
local pm=eb.fx(om)
local qm=pm.dmg/pm.cd/pm.hp/pm.speed*(1+(pm.range-1)/2)
for rm,sm in pairs(pm.kinds)do
qm=qm*(1+Q.rogueShare(rm)*sm)
end
if pm.ice>0 then
local tm=Q.rogueShare(ioc[1586])
qm=qm*(tm+(1-tm)/(1-pm.ice+pm.ice/W.modFactor(ioc[1615])))
end
if pm.fly>0 then
qm=qm*(1-pm.fly*0.5)
end
if pm.noCC then
qm=qm*0.95
end
if pm.shroud then
qm=qm*0.9
end
return qm
end
function eb.cardGems(um,vm)
local wm=0
local xm=eb.pearlsFrom(vm+1,50)
for ym,zm in pairs(type(um.effects)==ioc[1408]and um.effects or{})do
if type(zm)==ioc[1408]then
local Am=tonumber(zm.amount)or 0
if zm.type==ioc[1616]then
wm=wm+math.abs(Am)*xm*I.pearlValue
elseif zm.type==ioc[1617]then
local Bm,Cm=pcall(O.rewardValue,zm.reward)
if Bm then
wm=wm+(tonumber(Cm)or 0)
end
elseif zm.type==ioc[1618]then
wm=wm+Am*eb.STARFALL_GEMS
elseif zm.type==ioc[1619]then
wm=wm+Am*100
end
end
end
if um.option_type==ioc[1620]then
wm=wm+eb.HARD_GEMS
end
if um.weather then
local Dm=um.weather~=eb.weatherNow()
if Dm and um.weather==ioc[1621]then
wm=wm+eb.STARFALL_GEMS
end
local Em=eb.board()
if Dm and Em and um.weather~=ioc[1591]and not Em.weathers[um.weather]then
wm=wm+(1000+5000*I.pearlValue+50*(H.ITEM_VALUE.star_remnant_limited or 25))/eb.WEATHERS
end
end
return wm
end
