function eb.skinPlan()
local _m,an=H.session(),H.prof()
local bn=H.data(ioc[1543])or{}
local cn=(an.inventory and an.inventory.unique_items)or an.unique_items or{}
local dn,en={},{kinds={},sell={},wear={},pearls=0,missing={}}
for fn,gn in pairs(cn)do
local hn=type(gn)==ioc[1408]and H.Items[gn.item_id]
if hn and hn.item_group==ioc[1543]and hn._skin_set==eb.SKIN_SET and hn.usage and bn[hn.usage.skin_id]then
local jn=dn[gn.item_id]
if not jn then
jn={id=gn.item_id,name=hn.name,rarity=hn.rarity,skinId=hn.usage.skin_id,skin=bn[hn.usage.skin_id],uuids={}}
dn[gn.item_id]=jn
table.insert(en.kinds,jn)
end
table.insert(jn.uuids,gn.uuid or fn)
end
end
table.sort(en.kinds,function(kn,ln)
return kn.name<ln.name
end)
local mn=eb.team()
local nn=_m.profile_data.collection.owned_units
for pn,qn in ipairs(en.kinds)do
for rn,sn in pairs(nn)do
if eb.skinFits(sn.unit_id,qn.skin)then
qn.fits=true
break
end
end
local tn=qn.rarity==ioc[1646]or qn.rarity==ioc[1647]
qn.keep=(qn.fits or tn)and 1 or 0
for un=qn.keep+1,#qn.uuids do
table.insert(en.sell,{uuid=qn.uuids[un],name=qn.name,pearls=eb.SKIN_PRICE[qn.rarity]or 0})
en.pearls=en.pearls+(eb.SKIN_PRICE[qn.rarity]or 0)
end
end
for vn,wn in ipairs(mn)do
local xn=wn.skin and wn.skin._skin_id and bn[wn.skin._skin_id]
if not(xn and xn._skin_set==eb.SKIN_SET)then
for yn,zn in pairs(bn)do
if type(zn)==ioc[1408]and zn._skin_set==eb.SKIN_SET and eb.skinFits(wn.unit_id,zn)then
local An=yn..ioc[1648]
if dn[An]then
table.insert(en.wear,{uuid=dn[An].uuids[1],unit=wn.uuid,unitName=N.name(wn.unit_id),name=dn[An].name})
else
table.insert(en.missing,{item=An,unitName=N.name(wn.unit_id),name=zn.name,boost=tonumber(zn._damage_boost)or 0,drop=eb.SKIN_DROP[zn._skin_rarity]or 0})
end
end
end
end
end
return en
end
function eb.starPlan(Bn)
Bn=Bn or eb.skinPlan()
local Cn=H.Items[eb.STAR]or{}
local Dn=tonumber(Cn._mythic_unit_pity)or 400
local En=(H.prof().capsule_pity_data or{})[eb.STAR]or{}
local Fn=tonumber(En.opens_since_mythic_unit)or 0
local Gn={opened=tonumber(En.total_opens)or 0,left=math.max(1,Dn-Fn),units={}}
local Hn=tonumber(H.cur(ioc[1642]))or 0
Gn.can=math.max(0,math.floor((Hn-(tonumber(I.pearlFloor)or 0))/eb.STAR_COST))
local In={}
for Jn,Kn in pairs(H.session().profile_data.collection.owned_units)do
In[Kn.unit_id]=true
local Ln=H.Units[Kn.unit_id]
if Ln and Ln.evolved and Ln.evolved.from then
In[Ln.evolved.from]=true
end
end
for Mn,Nn in pairs(Cn.usage and Cn.usage.possible_rewards or{})do
local On=Nn.unit or Nn.item
if On and H.Units[On]and H.Units[On].rarity==ioc[1647]and not In[On]then
table.insert(Gn.units,N.name(On))
end
end
table.sort(Gn.units)
local Pn={}
if#Bn.missing>0 then
local Qn=Bn.missing[1]
table.insert(Pn,string.format(ioc[1649],Qn.name,Qn.unitName))
end
if#Gn.units>0 then
table.insert(Pn,string.format(ioc[1650],table.concat(Gn.units,ioc[1503])))
end
Gn.why=table.concat(Pn,ioc[1651])
Gn.open= #Pn>0 and math.min(Gn.can,#Gn.units>0 and Gn.left or 100)or 0
return Gn
end
function eb.skinText()
