table.insert(Un,string.format(ioc[1653],Wn.name,#Wn.uuids>1 and(ioc[1654].. #Wn.uuids)or ioc[337],(tonumber(Wn.skin._damage_boost)or 0)*100,Wn.fits and ioc[337]or ioc[1655]))
end
table.insert(Tn,ioc[1656]..(#Un>0 and table.concat(Un,ioc[1503])or ioc[1657])..ioc[1658])
if#Sn.wear>0 then
local Xn={}
for Yn,Zn in ipairs(Sn.wear)do
