end
table.insert(Tn,ioc[1660]..table.concat(Xn,ioc[1503])..ioc[1658])
end
for ao,bo in ipairs(Sn.missing)do
table.insert(Tn,string.format(ioc[1661],bo.name,bo.unitName,bo.boost*100,bo.drop*100))
end
if#Sn.sell>0 then
local co={}
