else
table.insert(Tn,ioc[1664])
end
local jo,ko=pcall(eb.starPlan,Sn)
if jo then
table.insert(Tn,string.format(ioc[1665],ko.opened,ko.left,M.fmt(ko.left*eb.STAR_COST)))
if ko.open>0 then
table.insert(Tn,string.format(ioc[1666],ko.open,M.fmt(ko.open*eb.STAR_COST),ko.why,M.fmt(I.pearlFloor)))
elseif ko.why~=ioc[337]then
table.insert(Tn,string.format(ioc[1667],ko.why,M.fmt(I.pearlFloor)))
else
table.insert(Tn,ioc[1668])
end
end
if P.pickNote.skins then
table.insert(Tn,P.pickNote.skins)
end
return table.concat(Tn,ioc[1419])
end
function eb.skinTick()
if not(I.skinSmart or I.starOpen)or not(J.live.event and eb.is(J.live.event.level))then
return
end
if(j.req.back.skins or 0)>M.now()then
return
end
local mo=H.session()
local function no(oo,po,qo)
local ro=j.gameSaid(po)
P.pickNote.skins=string.format(ioc[1669],oo,tostring(ro or qo or ioc[1670]))
j.log(1,ioc[1603],P.pickNote.skins)
j.backoff(ioc[1671],1800)
end
local so=eb.skinPlan()
if I.skinSmart then
local uo=so.wear[1]
if uo and(j.req.back.skinWear or 0)<=M.now()then
local vo=db.slotOf(uo.unit)
if vo then
J.str.reequip={uuid=uo.unit,slot=vo}
j.saveNow()
j.request(ioc[1672],ioc[1673],uo.unit)
local wo=M.now()
while M.now()-wo<4 and db.slotOf(uo.unit)do
task.wait(0.25)
end
end
local xo=M.now()
local yo,zo=j.request(ioc[1674],ioc[1675],uo.uuid,{unit_uuid=uo.unit})
local function Ao()
local Bo=mo.collection:get_unit_by_uuid(uo.unit)
return Bo and Bo.skin~=nil
end
while M.now()-xo<5 and not Ao()do
task.wait(0.25)
end
if vo then
db.reequip()
end
if Ao()then
j.log(1,ioc[1603],string.format(ioc[1676],uo.name,uo.unitName))
P.pickNote.skins=nil
so=eb.skinPlan()
else
local Co=j.gameSaid(xo)
P.pickNote.skins=string.format(ioc[1677],uo.name,tostring(Co or zo or ioc[1670]))
j.log(1,ioc[1603],P.pickNote.skins)
j.backoff(ioc[1674],1800)
end
end
if#so.sell>0 then
local Do,Eo={},0
for Fo=1,math.min(50,#so.sell)do
table.insert(Do,so.sell[Fo].uuid)
Eo=Eo+so.sell[Fo].pearls
end
local Go=tonumber(H.cur(ioc[1642]))or 0
local Ho=M.now()
local Io,Jo=j.request(ioc[1678],ioc[1679],Do)
while M.now()-Ho<5 and(tonumber(H.cur(ioc[1642]))or 0)<=Go do
task.wait(0.25)
end
local Ko=(tonumber(H.cur(ioc[1642]))or 0)-Go
if Ko<=0 then
return no(ioc[1680],Ho,Jo)
end
R.add(string.format(ioc[1681],#Do),#Do,ioc[1671],string.format(ioc[1682],M.fmt(Ko)))
P.pickNote.skins=nil
end
end
if I.starOpen then
local Lo=mo.inventory
local function Mo()
local No,Oo=pcall(Lo.get_number_of_owned_item,Lo,eb.STAR)
return No and tonumber(Oo)or 0
end
local Po=M.now()
for Qo=1,8 do
if M.now()-Po>15 or not j.alive or j.where~=ioc[1475]then
break
end
local Ro=Mo()
local So=eb.starPlan(eb.skinPlan())
local To=M.now()
if Ro>0 then
local Uo,Vo=j.request(ioc[1683],ioc[1684],eb.STAR,{use10=Ro>=10,use_all=false})
while M.now()-To<6 and Mo()>=Ro do
task.wait(0.25)
end
if Mo()>=Ro then
return no(ioc[1685],To,Vo)
end
j.log(1,ioc[1603],string.format(ioc[1686],Ro-Mo(),(tonumber(((H.prof().capsule_pity_data or{})[eb.STAR]or{}).total_opens)or 0)))
P.pickNote.skins=nil
elseif So.open>0 then
local Wo=So.open>=10 and 10 or 1
local Xo=tonumber(H.cur(ioc[1642]))or 0
local Yo,Zo=j.request(ioc[1687],ioc[1688],eb.STAR,ioc[1425],ioc[1689],tostring(Wo))
while M.now()-To<5 and Mo()<=0 do
task.wait(0.25)
end
if Mo()<=0 then
return no(ioc[1690],To,Zo)
end
R.add(string.format(ioc[1691],Mo()),Xo-(tonumber(H.cur(ioc[1642]))or 0),ioc[1692],ioc[1693]..So.why)
P.pickNote.skins=nil
else
break
end
end
end
end
function O.list()
local _o=H.prof()
if not _o then
