return Vt
end
Ut=Ut or Tt.id
local Wt=Tt.rewards
if type(Wt)==ioc[1408]and Wt.item then
Wt={Wt}
end
local Xt=false
for Yt,Zt in pairs(type(Wt)==ioc[1408]and Wt or{})do
if type(Zt)==ioc[1408]then
local au=M.list(Zt.item)
local bu=1
if Zt._item_multichoice and#au>0 then
bu=math.min(1,(tonumber(Zt._item_multichoice.min)or#au)/ #au)
end
for cu,du in ipairs(au)do
if type(du)==ioc[1408]and du.item_id then
local eu=tonumber(du.amount)or((tonumber(du.min_amount)or 1)+(tonumber(du.max_amount)or tonumber(du.min_amount)or 1))/2
table.insert(Vt,{item=du.item_id,per=eu*(tonumber(du.chance)or 1)*bu})
Xt=true
end
end
end
end
if not Xt then
for fu,gu in pairs(type(Tt._show_rewards)==ioc[1408]and Tt._show_rewards or{})do
if type(gu)==ioc[1408]and gu.type==ioc[1773]and gu.params and gu.params.item_id then
table.insert(Vt,{item=gu.params.item_id,per=1})
end
end
end
local hu,iu=pcall(U.hiveDrops,Ut)
if hu and iu then
local ju={}
for ku,lu in ipairs(Vt)do
ju[lu.item]=ku
end
for mu,nu in pairs(iu)do
if ju[mu]then
Vt[ju[mu]].per=nu
else
table.insert(Vt,{item=mu,per=nu})
