function ab.pullGoal()
local Iw=I.pullGoal
if type(Iw)~=ioc[1410]or Iw==ioc[337]or type(H.Units[Iw])~=ioc[1408]then
return nil
end
local Jw=H.prof()
if not Jw then
return nil
end
local Kw=H.Units[Iw]
local Lw=Kw.evolve and Kw.evolve.evolve_unit or Iw
local Mw={id=Iw,to=Lw,coins=H.cur(ioc[1803]),itemCost=0,needCoins=0}
for Nw,Ow in pairs(Kw.evolve and Kw.evolve.normal and Kw.evolve.normal.item_requirement or{})do
local Pw=H.SaleEvent[Ow.item_id]
if Pw and type(Pw.resource_cost)==ioc[1408]and Pw.resource_cost.id==ioc[1803]then
Mw.item,Mw.itemCost=Ow.item_id,tonumber(Pw.resource_cost.amount)or 0
end
end
Mw.haveItem=Mw.item~=nil and ab.have(Mw.item)>0
local Qw,Rw=P.hatched[Iw]or false,false
for Sw,Tw in pairs(Jw.collection.owned_units)do
if Tw.unit_id==Iw then
Qw=true
end
if Tw.unit_id==Lw then
Rw=true
end
end
if Rw then
Mw.step=ioc[1804]
elseif not Qw then
Mw.step,Mw.needCoins=ioc[1805],1
elseif Mw.item and not Mw.haveItem then
Mw.step,Mw.needCoins=ioc[1773],math.max(0,Mw.itemCost-Mw.coins)
else
Mw.step=ioc[1806]
end
return Mw
end
