if not H.Banners.April2025 then
return Ww..string.format(ioc[1810],N.name(Uw.id))
end
local Xw=math.max(I.aprilFloor,Uw.haveItem and 0 or Uw.itemCost)
local Yw=Vw and Vw.pity_data and Vw.pity_data.April2025
local Zw=Yw and tonumber(Yw.opens_since_mythic)
return Ww..string.format(ioc[1811]..ioc[1812]..ioc[1813],N.name(Uw.id),M.fmt(Uw.coins),math.max(0,math.floor((Uw.coins-Xw)/1500)),M.fmt(Xw),N.name(Uw.id),Zw and string.format(ioc[1814],Zw)or ioc[337],math.max(I.aprilValue,I.goalCoinValue),I.summonApril and ioc[1815]or ioc[1816])
elseif Uw.step==ioc[1773]then
return Ww..string.format(ioc[1817],N.name(Uw.id),M.fmt(Uw.itemCost),M.fmt(Uw.coins))
elseif Uw.step==ioc[1806]then
return Ww..ioc[1818]
end
return Ww..ioc[1819]
end
function P.eventShop()
