function ab.planItem(Jx,Kx)
local Lx=ab.have(Jx)
if Lx>=Kx then
return{item=Jx,done=true}
end
local Mx=ab.sources()[Jx]
if Mx and Mx[1]then
return{item=Jx,need=Kx,have=Lx,farm=Jx,farmNeed=Kx-Lx,levels=Mx}
end
local Nx=H.SaleEvent[Jx]
if Nx and type(Nx.resource_cost)==ioc[1408]then
return{item=Jx,need=Kx,have=Lx,eventShop=true,cost=tonumber(Nx.resource_cost.amount)or 0,currency=Nx.resource_cost.id,farmNeed=0}
end
for Ox,Px in pairs(J.raidShop)do
if Px.id==Jx and Px.costItem and(Px.stock==ioc[1836]or(tonumber(Px.stock)or 0)>0)then
local Qx=ab.sources()[Px.costItem]
local Rx=Px.cost*(Kx-Lx)
local Sx=ab.have(Px.costItem)
return{item=Jx,need=Kx,have=Lx,shopKey=Ox,costItem=Px.costItem,cost=Px.cost,farm=Px.costItem,farmNeed=math.max(0,Rx-Sx),levels=Qx or{}}
end
end
for Tx,Ux in pairs(O.PORTALS)do
if Ux.item==Jx then
return{item=Jx,need=Kx,have=Lx,farm=Jx,farmNeed=Kx-Lx,portal=Tx,levels={{level=Ux.level,per=O.portalPer(Tx)}}}
end
end
return{item=Jx,need=Kx,have=Lx,unknown=true}
end
