cb.LUCK_RESERVE=500
cb.MIN_WORTH=0.02
cb.TOP_WORTH=0.08
function cb.shop(gsb,hsb)
local isb=cb.cleared(gsb)
local jsb=cb.res(gsb)
local ksb=1+0.1*(cb.items(gsb)._curse_shop or 0)
local lsb=cb.shopAhead(gsb)and math.ceil(cb.LUCK_RESERVE*ksb)or 0
local msb={}
local nsb,osb={},0
for psb,qsb in ipairs(cb.offers(hsb and hsb.data))do
qsb.cost=math.ceil(qsb.cost*ksb)
table.insert(nsb,tostring(cb.item(qsb.id).name or qsb.id))
if not qsb.bought and not cb.isCurse(qsb.id)then
qsb.luck=tonumber(cb.item(qsb.id).luck_increase)~=nil
qsb.v=cb.itemValue(qsb.id,gsb)
if not qsb.luck and qsb.v/math.max(1,qsb.cost)<cb.MIN_WORTH then
osb=osb+1
elseif qsb.v>0 and(qsb.luck or isb>=10 or qsb.v/math.max(1,qsb.cost)>=cb.TOP_WORTH)then
table.insert(msb,qsb)
end
end
end
table.sort(msb,function(rsb,ssb)
if rsb.luck~=ssb.luck then
return rsb.luck
end
return rsb.v/math.max(1,rsb.cost)>ssb.v/math.max(1,ssb.cost)
end)
local tsb,usb,vsb={},0,0
for wsb,xsb in ipairs(msb)do
if xsb.cost<=jsb-(xsb.luck and 0 or lsb)then
if cb.buy(xsb)then
jsb=cb.res(cb.data())
table.insert(tsb,string.format(ioc[2595],tostring(cb.item(xsb.id).name or xsb.id),xsb.cost))
end
elseif xsb.cost<=jsb then
vsb=vsb+1
else
usb=usb+1
end
end
cb.note(string.format(ioc[2596],isb,#nsb>0 and table.concat(nsb,ioc[1503])or ioc[2597],#tsb>0 and(ioc[2598]..table.concat(tsb,ioc[1503]))or(isb<10 and ioc[2599]or(vsb>0 and ioc[2600]or ioc[2601])),jsb,usb>0 and string.format(ioc[2602],usb)or ioc[337],vsb>0 and string.format(ioc[2603],vsb,lsb)or ioc[337],osb>0 and string.format(ioc[2604],osb)or ioc[337]))
j.request(ioc[2605],ioc[2606])
