if not(atb or ftb>=cb.ROOMS or etb<=1)then
cb.note(string.format(ioc[2619],ftb,ctb,dtb,cb.luck(_sb)))
j.request(ioc[2605],ioc[2606])
return
end
local gtb,htb,itb=0,0,0
local jtb=tonumber(H.cur(ioc[1468]))or 0
local ktb=cb.wallet()
for ltb=1,ctb+dtb+4 do
local mtb,ntb,otb=cb.res(cb.data())
if ntb+otb<=0 or itb>=2 then
break
end
local ptb,qtb
if ntb>0 then
ptb,qtb=j.request(ioc[2620],ioc[2621])
else
ptb,qtb=j.request(ioc[2620],ioc[2621],true)
end
if ptb and qtb~=nil then
j.log(1,ioc[2589],ioc[2622]..(type(qtb)==ioc[1408]and M.json(M.plain(qtb)):sub(1,300)or tostring(qtb)))
end
local rtb=M.now()
while M.now()-rtb<4 do
local stb,ttb,utb=cb.res(cb.data())
if ttb<ntb or utb<otb then
break
end
task.wait(0.25)
end
local vtb,wtb,xtb=cb.res(cb.data())
if wtb<ntb then
gtb=gtb+(ntb-wtb)
itb=0
elseif xtb<otb then
htb=htb+(otb-xtb)
itb=0
else
itb=itb+1
end
task.wait(1)
if wtb<ntb or xtb<otb then
local ytb=cb.wallet()
local ztb=cb.walletDiff(ktb,ytb)
j.log(1,ioc[2589],(xtb<otb and ioc[2623]or ioc[2622])..ztb)
J.dg.pay=J.dg.pay or{}
local Atb={}
for Btb,Ctb in pairs(ytb.items)do
if Ctb~=(ktb.items[Btb]or 0)then
Atb[Btb]=Ctb-(ktb.items[Btb]or 0)
end
end
table.insert(J.dg.pay,{at=os.time(),rare=xtb<otb,gems=ytb.gems-ktb.gems,luck=cb.luck(_sb),paid=ztb,items=Atb})
while#J.dg.pay>60 do
table.remove(J.dg.pay,1)
end
ktb=ytb
end
end
cb.note(string.format(ioc[2624],gtb,htb,atb and ioc[2625]or(etb<=1 and ioc[2626]or ioc[2627]),cb.luck(_sb),(tonumber(H.cur(ioc[1468]))or 0)-jtb))
local Dtb,Etb,Ftb=cb.res(cb.data())
if(atb or ftb>=cb.ROOMS)and Etb+Ftb>0 then
cb.note(string.format(ioc[2628],Etb,Ftb))
O.rec(ioc[1727]).restUntil=os.time()+1800
return ioc[2629]
end
if not atb then
j.request(ioc[2605],ioc[2606])
end
end
