for Dwb=0,Cwb-1 do
local Ewb=zwb:Lerp(Awb,Dwb/Cwb)
table.insert(Q.samples,{pos=Ewb,prog=(xwb+Bwb*Dwb/Cwb)/math.max(1,vwb),lane=qwb.Name})
