Q.placeLog=Q.placeLog or{}
table.insert(Q.placeLog,{t=math.floor(M.now()-(Q.startT or M.now())),w=Q.wave(),id=oJb.id,x=math.floor(rJb.X),z=math.floor(rJb.Z),cover=math.floor((sJb or 0)+0.5),why=tostring(pJb):sub(1,90)})
j.status(ioc[2767],string.format(ioc[2782],N.name(oJb.id),pJb))
