Q.noSpot[oJb.uuid]=3
j.log(1,ioc[2772],string.format(ioc[2783],N.name(oJb.id),Q.fieldCount(),Q.FIELD_MAX))
end
end
if uJb and tJb>=(oJb.data.cost or 0)and not Q.random then
local wJb=Q.spotKey(rJb)
