local xJb=Q.mapKey()
J.blocked[xJb]=J.blocked[xJb]or{}
if not Q.refusedRun[wJb]then
J.blocked[xJb][wJb]=(tonumber(J.blocked[xJb][wJb])or 0)+1
Q.refusedRun[wJb]=true
end
Q.refusals=(Q.refusals or 0)+1
Q.unitRefusals[oJb.uuid]=(Q.unitRefusals[oJb.uuid]or 0)+1
if Q.unitRefusals[oJb.uuid]>=3 then
local yJb=math.max(1,Q.count(oJb.uuid))
if J.caps[oJb.uuid]~=yJb then
J.caps[oJb.uuid]=yJb
j.log(1,ioc[2772],string.format(ioc[2784],N.name(oJb.id),yJb))
end
end
j.log(2,ioc[2772],ioc[2785]..wJb..ioc[1823]..N.name(oJb.id))
j.saveSoon()
end
return false
end
