table.insert(Q.trialTrace,string.format(ioc[2787],JJb,IJb-(Q.startT or IJb),KJb,table.concat(MJb,ioc[1885]),OJb,NJb+UJb,#(Q.enemies or{}),Q.hpAliveRaw or 0,Q.waveMax[JJb-1]or 0,Q.teamDps or 0))
end
if GJb.lastW and GJb.lastW>0 and GJb.lastWT then
