end
local bKb=math.min(30,IJb-(Q.startT or IJb))
Q.incomeRate=bKb>=8 and ZJb/bKb or nil
for cKb,dKb in ipairs(Q.enemies)do
local eKb=dKb.m
local fKb=Q.track[eKb]
if not fKb then
