J.maps[KMb]=J.maps[KMb]or{}
local MMb=J.maps[KMb]
MMb.walkN=(tonumber(MMb.walkN)or 0)+1
MMb.walk=LMb and(LMb+(JMb-LMb)*math.max(0.2,1/(MMb.walkN+1)))or JMb
W._walk[KMb]=MMb.walk
end
end
if(BMb.potSum or 0)>0 and(BMb.dealtSum or 0)>0 then
GMb(ioc[2802],M.clamp(BMb.dealtSum/BMb.potSum,0.1,2))
