local RMb=type(J.maps[NMb].dens)==ioc[1408]and J.maps[NMb].dens or{}
local SMb=(tonumber(J.maps[NMb].densN)or 0)+1
for TMb=1,W.BINS do
local UMb=(BMb.dens[TMb]or 0)/OMb
