RMb[TMb]=VMb and(VMb+(UMb-VMb)*math.max(0.2,1/SMb))or UMb
end
J.maps[NMb].dens,J.maps[NMb].densN=RMb,SMb
end
if#BMb.pay>=2 then
GMb(ioc[2803],M.clamp(EMb(BMb.pay),0.5,2))
end
if not Q.joinedMid then
GMb(ioc[2804],EMb(BMb.waveSec))
GMb(ioc[2805],EMb(BMb.baseRel))
CMb.baseDps=nil
GMb(ioc[2806],EMb(BMb.skip))
local WMb={}
for XMb=2,Q.wave()-1 do
local YMb,ZMb=tonumber(BMb.spawn[tostring(XMb)]),tonumber(BMb.spawnLast[tostring(XMb)])
if YMb and ZMb and YMb>=3 then
table.insert(WMb,ZMb/(YMb-1))
end
end
if#WMb>=3 then
GMb(ioc[2807],M.clamp(EMb(WMb),0.05,5))
end
local _Mb=tonumber(CMb.voteAt)or(Q.info and Q.info.voteAt)or W.PRIOR.voteAt
